import{_ as i,c as a,o as r,ag as t}from"./chunks/framework.W0M1DOUF.js";const d="/blog/assets/img.CZjCjyVj.png",o="/blog/assets/img_1.sbNzU38A.png",u=JSON.parse('{"title":"【Android】针对非 SDK 接口的限制","description":"","frontmatter":{},"headers":[],"relativePath":"android/版本兼容/【Android】针对非 SDK 接口的限制.md","filePath":"android/版本兼容/【Android】针对非 SDK 接口的限制.md"}'),n={name:"android/版本兼容/【Android】针对非 SDK 接口的限制.md"};function l(s,e,p,c,h,_){return r(),a("div",null,e[0]||(e[0]=[t('<h1 id="【android】针对非-sdk-接口的限制" tabindex="-1">【Android】针对非 SDK 接口的限制 <a class="header-anchor" href="#【android】针对非-sdk-接口的限制" aria-label="Permalink to &quot;【Android】针对非 SDK 接口的限制&quot;">​</a></h1><ul><li><p>官方介绍：<a href="https://developer.android.google.cn/guide/app-compatibility/restrictions-non-sdk-interfaces?hl=zh-cn" target="_blank" rel="noreferrer">https://developer.android.google.cn/guide/app-compatibility/restrictions-non-sdk-interfaces?hl=zh-cn</a></p></li><li><p>工具下载（2024.11月搬运过来）：veridex 及 15-11 非 sdk 接口的名单 <a href="https://www.alipan.com/s/J5t4bFWJzz6" target="_blank" rel="noreferrer">https://www.alipan.com/s/J5t4bFWJzz6</a> 提取码: 9l1b</p></li></ul><h2 id="区分-sdk-接口和非-sdk-接口" tabindex="-1">区分 SDK 接口和非 SDK 接口 <a class="header-anchor" href="#区分-sdk-接口和非-sdk-接口" aria-label="Permalink to &quot;区分 SDK 接口和非 SDK 接口&quot;">​</a></h2><ul><li>sdk 接口：平时开发中可以正常调用到的 android.jar api. <code>如 ActivityManager.killBackgroundProcesses(String packageName)</code></li><li>非 sdk 接口： android系统源代码中，隐藏的api. 如 <code> ActivityManager.forceStopPackage(String packageName)</code> 这种需要通过反射调用的。当然还包括 jni 层面的句柄。</li><li>非 android.jar 的api 是不受影响的。</li></ul><h2 id="非-sdk-接口-的分类" tabindex="-1">非 SDK 接口 的分类 <a class="header-anchor" href="#非-sdk-接口-的分类" aria-label="Permalink to &quot;非 SDK 接口 的分类&quot;">​</a></h2><ul><li><p><a href="https://developer.android.google.cn/guide/app-compatibility/restrictions-non-sdk-interfaces?hl=zh-cn#list-names" target="_blank" rel="noreferrer">https://developer.android.google.cn/guide/app-compatibility/restrictions-non-sdk-interfaces?hl=zh-cn#list-names</a></p></li><li><p>黑名单(blocked)：受限，无论目标 SDK 如何。 平台将表现为似乎接口并不存在。 例如，无论应用何时尝试使用接口，平台都会引发 NoSuchMethodError/NoSuchFieldException，即使应用想要了解某个特殊类别的字段/函数名单，平台也不会包含接口。</p></li><li><p>(max-target-x)：这些名单会以应用无法再访问相应名单中的非 SDK 接口之前可以作为目标平台的最高 API 级别 (max-target-x) 进行标记。例如，在 Android Pie 中未被屏蔽，但现在已被 Android 10 屏蔽的非 SDK 接口会列入 max-target-p (greylist-max-p) 名单，其中“p”表示 Pie 或 Android 9（API 级别 28）。</p></li><li><p>灰名单（unsupported）：仍可以访问的非 SDK 函数/字段，但不保证后续不会移到黑名单。</p></li><li><p>白名单：该列表的API可以自由使用。</p></li></ul><h2 id="使用-veridex-检测" tabindex="-1">使用 veridex 检测 <a class="header-anchor" href="#使用-veridex-检测" aria-label="Permalink to &quot;使用 veridex 检测&quot;">​</a></h2><p><img src="'+d+'" alt="veridex"></p><h2 id="使用-android-studio-lint-工具进行测试" tabindex="-1">使用 Android Studio lint 工具进行测试 <a class="header-anchor" href="#使用-android-studio-lint-工具进行测试" aria-label="Permalink to &quot;使用 Android Studio lint 工具进行测试&quot;">​</a></h2><p><img src="'+o+'" alt="Android studio lint"></p>',10)]))}const m=i(n,[["render",l]]);export{u as __pageData,m as default};
